void DrawClippedRectangleOutline(
	int16 left, int16 top, int16 right, int16 bottom, uint16 color)
{
	if (left < VIDEO_SCREEN_MIN_X)
		left = VIDEO_SCREEN_MIN_X;
	if (right < VIDEO_SCREEN_MIN_X)
		right = VIDEO_SCREEN_MIN_X;
	if (left > VIDEO_SCREEN_MAX_X)
		left = VIDEO_SCREEN_MAX_X;
	if (right > VIDEO_SCREEN_MAX_X)
		right = VIDEO_SCREEN_MAX_X;

	if (top < VIDEO_SCREEN_MIN_Y)
		top = VIDEO_SCREEN_MIN_Y;
	if (bottom < VIDEO_SCREEN_MIN_Y)
		bottom = VIDEO_SCREEN_MIN_Y;
	if (top > VIDEO_SCREEN_MAX_Y)
		top = VIDEO_SCREEN_MAX_Y;
	if (bottom > VIDEO_SCREEN_MAX_Y)
		bottom = VIDEO_SCREEN_MAX_Y;

	DrawClippedAxisAlignedLine(left, top, right, top, color);
	DrawClippedAxisAlignedLine(left, bottom, right, bottom, color);
	DrawClippedAxisAlignedLine(left, top, left, bottom, color);
	DrawClippedAxisAlignedLine(right, top, right, bottom, color);
}
